package com.arqly.backend.entity;import jakarta.persistence.*;import java.math.*;import java.time.*;
@Entity @Table(name="financial_settlements") public class FinancialSettlement extends BaseEntity {@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="installment_id",nullable=false)private FinancialInstallment installment;@Column(nullable=false,precision=15,scale=2)private BigDecimal amount;@Column(nullable=false)private LocalDate settlementDate;@Enumerated(EnumType.STRING)@Column(nullable=false)private PaymentMethod paymentMethod;@Column(columnDefinition="text")private String description;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="created_by_id")private TenantUser createdBy;private Instant reversedAt;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="reversed_by_id")private TenantUser reversedBy;private String reversalReason;public FinancialInstallment getInstallment(){return installment;}public void setInstallment(FinancialInstallment v){installment=v;}public BigDecimal getAmount(){return amount;}public void setAmount(BigDecimal v){amount=v;}public LocalDate getSettlementDate(){return settlementDate;}public void setSettlementDate(LocalDate v){settlementDate=v;}public PaymentMethod getPaymentMethod(){return paymentMethod;}public void setPaymentMethod(PaymentMethod v){paymentMethod=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public TenantUser getCreatedBy(){return createdBy;}public void setCreatedBy(TenantUser v){createdBy=v;}public Instant getReversedAt(){return reversedAt;}public void setReversedAt(Instant v){reversedAt=v;}public TenantUser getReversedBy(){return reversedBy;}public void setReversedBy(TenantUser v){reversedBy=v;}public String getReversalReason(){return reversalReason;}public void setReversalReason(String v){reversalReason=v;}}
